    "d1.title": "New car and SUV registrations",
    "d1.lead": "An analysis of new car and SUV sales in Spain since 2015. The front page sums up the market —the trend in registrations, the weight of leasing, average CO₂ emissions, the powertrain mix and the take-off of the electric car— and leads to six thematic dashboards.",
    "d1.record": "<div><dt>Period</dt><dd>Since 2015</dd></div> <div><dt>Updated</dt><dd>Monthly, on the 15th</dd></div> <div><dt>Source</dt><dd><a href=\"https://www.dgt.es/menusecundario/dgt-en-cifras/dgt-en-cifras-resultados/dgt-en-cifras-detalle/Microdatos-de-Matriculaciones-de-Vehiculos-mensual/\" target=\"_blank\" rel=\"noopener\">DGT registration microdata</a></dd></div>",
    "d1.video1t": "Car registrations: year-to-date analysis",
    "d1.video1": "<svg aria-hidden=\"true\"><use href=\"#i-play\"/></svg>Video: YTD analysis",
    "d1.video2t": "Car registrations: the other dashboards",
    "d1.video2": "<svg aria-hidden=\"true\"><use href=\"#i-play\"/></svg>Video: the other dashboards",
    "d1.stats": "<li class=\"stat\"><span class=\"stat__value\">8.76%</span><span class=\"stat__text\">electric (BEV) share in 2025, up from 0.11% in 2015</span></li> <li class=\"stat\"><span class=\"stat__value\">6.65%</span><span class=\"stat__text\">of registrations are diesel; in 2015 they were 63.44%</span></li> <li class=\"stat\"><span class=\"stat__value\">104.2<small> g/km</small></span><span class=\"stat__text\">average CO₂ per new vehicle, 19.8% less than in 2021</span></li> <li class=\"stat\"><span class=\"stat__value\">24.45%</span><span class=\"stat__text\">of sales go to leasing (10.81% in 2015)</span></li>",
    "d1.vizTitle": "New car and SUV registrations",
    "d1.tabsAria": "Car and SUV registration dashboards",
