    "d3.title": "The vehicle fleet in Spain",
    "d3.lead": "An analysis of every vehicle on the road in Spain on the last day of each year, from 2021 to 2025: environmental label, age, average CO₂ emissions and year of first registration. The front page leads to two dashboards: the yearly evolution of the fleet and an analysis by powertrain, brand and province.",
    "d3.record": "<div><dt>Period</dt><dd>2021 to 2025, as of 31 December</dd></div> <div><dt>Updated</dt><dd>Yearly, around April</dd></div> <div><dt>Source</dt><dd><a href=\"https://www.dgt.es/menusecundario/dgt-en-cifras/dgt-en-cifras-resultados/dgt-en-cifras-detalle/Microdatos-de-parque-de-vehiculos-Anual/\" target=\"_blank\" rel=\"noopener\">DGT vehicle fleet microdata</a></dd></div>",
    "d3.video1t": "Spain’s vehicle fleet",
    "d3.video1": "<svg aria-hidden=\"true\"><use href=\"#i-play\"/></svg>Explainer video",
    "video.valdesParkT": "The vehicle fleet, with Luis Valdés",
    "video.valdes": "<svg aria-hidden=\"true\"><use href=\"#i-play\"/></svg>Video with Luis Valdés",
    "d3.statsLabel": "The fleet as of 31 December 2025",
    "d3.stats": "<li class=\"stat\"><span class=\"stat__value\">38.64<small> M</small></span><span class=\"stat__text\">vehicles make up the Spanish fleet</span></li> <li class=\"stat\"><span class=\"stat__value\">15.87<small> years</small></span><span class=\"stat__text\">average age: a very old fleet</span></li> <li class=\"stat\"><span class=\"stat__value\">2.16%</span><span class=\"stat__text\">carry the ZERO label (1.14% BEV and 1.02% plug-in hybrids)</span></li> <li class=\"stat\"><span class=\"stat__value\">104.9<small> g/km</small></span><span class=\"stat__text\">average CO₂ across the fleet (112.66 for cars)</span></li>",
    "d3.vizTitle": "The vehicle fleet in Spain",
    "d3.tabsAria": "Vehicle fleet dashboards",
    "d3.tab1": "Front page",
    "d3.tab1d": "A snapshot of the fleet on 31 December: environmental label, average age, CO₂ emissions and year of first registration.",
    "d3.tab2": "Year by year",
    "d3.tab2d": "The make-up of the fleet each year by powertrain and registration date. Each row is the fleet on the last day of the year.",
    "d3.tab3": "Fleet analysis",
    "d3.tab3d": "Fleet metrics by powertrain, brand, province and more, with a metric selector: number of vehicles, average CO₂ emissions, age and so on.",
    "d4.title": "Car and SUV ownership transfers",
    "d4.lead": "An analysis of the used-car market: ownership transfers of cars and SUVs in Spain since 2022. It follows the same structure as the registration analysis —a front page with the overview and six thematic dashboards— and adds the average age of the transferred vehicle.",
    "d4.record": "<div><dt>Period</dt><dd>Since 2022</dd></div> <div><dt>Updated</dt><dd>Monthly, on the 15th</dd></div> <div><dt>Source</dt><dd><a href=\"https://www.dgt.es/menusecundario/dgt-en-cifras/dgt-en-cifras-resultados/dgt-en-cifras-detalle/Microdatos-de-Transferencias-de-Vehiculos-mensual/\" target=\"_blank\" rel=\"noopener\">DGT transfer microdata</a></dd></div>",
    "video.valdesUsedT": "The used-car market, with Luis Valdés",
    "d4.video1": "<svg aria-hidden=\"true\"><use href=\"#i-play\"/></svg>Video with Luis Valdés",
    "d4.stats": "<li class=\"stat\"><span class=\"stat__value\">3.36<small> M</small></span><span class=\"stat__text\">transfers in 2025, 33.52% more than in 2022</span></li> <li class=\"stat\"><span class=\"stat__value\">48.06%</span><span class=\"stat__text\">of transferred cars are diesel (56.1% in 2022)</span></li> <li class=\"stat\"><span class=\"stat__value\">1.29%</span><span class=\"stat__text\">electric (BEV) share in the used-car market</span></li> <li class=\"stat\"><span class=\"stat__value\">11.7<small> years</small></span><span class=\"stat__text\">average age of the transferred vehicle</span></li>",
