    "d3.stats": "<li class=\"stat\"><span class=\"stat__value\">38,64<small> M</small></span><span class=\"stat__text\">ibilgailuk osatzen dute Espainiako parkea</span></li> <li class=\"stat\"><span class=\"stat__value\">15,87<small> urte</small></span><span class=\"stat__text\">batez besteko antzinatasuna: parke oso zaharkitua</span></li> <li class=\"stat\"><span class=\"stat__value\">% 2,16</span><span class=\"stat__text\">du ZERO etiketa (% 1,14 BEV eta % 1,02 hibrido entxufagarriak)</span></li> <li class=\"stat\"><span class=\"stat__value\">104,9<small> g/km</small></span><span class=\"stat__text\">CO₂ batez beste parkean (112,66 turismoetan)</span></li>",
