    "navarra.find3Bars": "<li style=\"--v: 153\"><span class=\"hbars__name\">Diesela</span><span class=\"hbars__track\" aria-hidden=\"true\"><span class=\"hbars__bar\"></span></span><span class=\"hbars__value\">153,0</span></li> <li style=\"--v: 136.1\"><span class=\"hbars__name\">Gasolina</span><span class=\"hbars__track\" aria-hidden=\"true\"><span class=\"hbars__bar\"></span></span><span class=\"hbars__value\">136,1</span></li> <li style=\"--v: 119.4\"><span class=\"hbars__name\">Hibridoa (HEV)</span><span class=\"hbars__track\" aria-hidden=\"true\"><span class=\"hbars__bar\"></span></span><span class=\"hbars__value\">119,4</span></li> <li style=\"--v: 114.1\"><span class=\"hbars__name\">Gasa (GLP eta GNC)</span><span class=\"hbars__track\" aria-hidden=\"true\"><span class=\"hbars__bar\"></span></span><span class=\"hbars__value\">114,1</span></li> <li style=\"--v: 46.3\"><span class=\"hbars__name\">Hibrido entxufagarria</span><span class=\"hbars__track\" aria-hidden=\"true\"><span class=\"hbars__bar\"></span></span><span class=\"hbars__value\">46,3</span></li> <li style=\"--v: 0\"><span class=\"hbars__name\">Elektrikoa (BEV)</span><span class=\"hbars__track\" aria-hidden=\"true\"><span class=\"hbars__bar\"></span></span><span class=\"hbars__value\">0,0</span></li>",
    "navarra.find3Caption": "Batez besteko CO₂a motorizazioka, 2026ko urtarrila–apirila, g/km-tan.",
    "navarra.find3Text1": "Nahasketan elektriko gehiago daudenez, batez bestekoa % 15,31 jaitsi da urtebetean: 2025eko urtarrila–apirileko 101 g/km inguruko datutik 2026ko 85,55 g/km-ra. Martxoan eta apirilean 80 g/km-tik behera geratu zen.",
    "navarra.find3Text2": "Salbuespena hibrido entxufagarriak dira: 18,3tik 46,3 g/km-ra igo dira (+% 140,46). Arrazoi nagusia Euro 6e-bis araua da, 2026ko urtarrilaren 1etik aurrera auto berrientzat derrigorrezkoa: entseguen erreferentziazko distantzia 2.200 km-ra igotzen du eta hobeto islatzen du benetako erabileran zenbat isurtzen duten. Horrez gain, modelo berriak gero eta indartsuagoak eta astunagoak dira.",
    "navarra.find4Title": "Nafarroa, gainerako probintzien aldean",
    "navarra.find4Text": "Batez besteko isurietan, Nafarroaren atzetik (85,55 g/km) Madril (89,19), Guadalajara (90,54) eta Toledo (90,99) datoz. Merkatuaren banaketan ere badira aldeak: Hyundai-Kiak proportzioan gehiago saltzen du Nafarroan gainerako probintzietan baino (turismoen % 13,96 hemen, % 10,45 han), eta Toyotari kontrakoa gertatzen zaio (% 9,10 eta % 13,37).",
    "navarra.policyTitle": "Mugikortasun elektrikoari emandako laguntza publikoa",
    "navarra.policyText1": "Nafarroaren aurrerabideak Nafarroako Gobernuko <a href=\"https://www.navarra.es/es/gobierno-de-navarra/departamento-de-industria-y-transicion-ecologica-y-digital-empresarial\" target=\"_blank\" rel=\"noopener\">Industria eta Trantsizio Ekologiko eta Enpresa Digitalerako Departamentuaren</a> laguntzak eta plangintza izan ditu lagun; <a href=\"https://www.navarra.es/es/-/altos-cargos/consejero-de-industria-y-transicion-ecologica-y-digital-empresarial\" target=\"_blank\" rel=\"noopener\">Mikel Irujo</a> kontseilaria da departamentuko arduraduna. 2021etik 2026ko otsailera bitartean, MOVES programaren 8.500 eskaera baino gehiago izapidetu zituen elektrikoak erosteko eta karga-puntuak jartzeko, eta 30,7 milioi euro eman zituen.",
    "navarra.policyText2": "Matrikulazioen mikrodatuek ez dute laguntza bakoitzaren eragina bereizten uzten, baina testuingurua ematen dute: mugikortasun elektrikoaren agendak helburu zuen 2026an matrikulatutako hiru ibilgailutik bat elektrikoa izatea, eta partikularren turismoetan entxufagarriek % 35,29 osatzen dute jada urtarriletik apirilera. Agendak matrikulazio guztiak neurtzen ditu, eta, beraz, bi zifrak ez dira erabat alderagarriak.",
    "navarra.policySubhead": "Departamentuaren eta Irujo kontseilariaren argitalpenak",
    "navarra.policyTimeline": "<li> <span class=\"cv__when\"><time datetime=\"2024-04-18\">2024ko apirila</time></span> <div class=\"cv__what\"> <strong><a href=\"https://www.navarra.es/es/-/nota-prensa/el-desarrollo-de-la-agenda-de-impulso-a-la-movilidad-electrica-en-navarra-hace-que-el-numero-de-puntos-de-recarga-de-vehiculo-electrico-se-duplique-en-menos-de-dos-anos\" target=\"_blank\" rel=\"noopener\">Karga-puntuak bikoiztu egin dira bi urte bete gabe</a></strong> <span>MUBIL azokan, Irujo kontseilariak karga-sarearen hazkundea mugikortasun elektrikoa bultzatzeko agendaren barruan kokatu zuen.</span> </div> </li> <li> <span class=\"cv__when\"><time datetime=\"2024-10-10\">2024ko urria</time></span> <div class=\"cv__what\"> <strong><a href=\"https://www.navarra.es/es/-/nota-prensa/industria-actualiza-la-agenda-navarra-de-impulso-a-la-movilidad-electrica-incluyendo-entre-sus-novedades-la-electrificacion-del-transporte-pesado\" target=\"_blank\" rel=\"noopener\">Mugikortasun Elektrikoaren Agenda, 2025–2026ko lan-plana</a></strong> <span>Irujok agenda eguneratua aurkeztu zuen: 2026an hiru ibilgailutik bat elektrikoa izatea du helburu, eta garraio astunaren elektrifikazioa da berrikuntza nagusia.</span> </div> </li> <li> <span class=\"cv__when\"><time datetime=\"2026-02-16\">2026ko otsaila</time></span> <div class=\"cv__what\"> <strong><a href=\"https://www.navarra.es/es/-/nota-prensa/industria-presenta-tximista-auto-el-nuevo-programa-foral-de-impulso-a-la-movilidad-electrica-dotado-con-4-7-millones-de-euros\" target=\"_blank\" rel=\"noopener\">Tximista Auto plana, 4,7 milioi eurorekin</a></strong> <span> Funts propioekin emandako laguntzak, 2026ko urtarrilaren 1etik aurrera egindako erosketetarako: 5.500&nbsp;€ arte Europan muntatutako elektriko batengatik eta 3.000&nbsp;€ kanpoan muntatuz gero, karga-puntuez gain. Irujoren arabera, «ibilgailu elektrikoaren erosketa sustatu nahi du, eta Europako Km0 industria babestu».</span> </div> </li> <li> <span class=\"cv__when\"><time datetime=\"2026-07-30\">2026ko uztaila</time></span> <div class=\"cv__what\"> <strong><a href=\"https://www.navarra.es/es/-/nota-prensa/el-plan-tximista-auto-agota-sus-fondos-tras-la-alta-demanda-de-ayudas-para-vehiculos-electricos-y-puntos-de-recarga\" target=\"_blank\" rel=\"noopener\">Tximista Autok funtsak agortu ditu</a></strong> <span>830 laguntza ordaindu dira, batez beste 35 eguneko epearekin. Estatuko Auto+ programaren irekierarekin bat egin du; azken hori ez da bateragarria foru-laguntzarekin.</span> </div> </li>",
    "navarra.policySource": "Iturria: Nafarroako Gobernuaren prentsa-oharrak, navarra.es atarian.",
